import java.util.*;

public class Main {
    interface Bean {}
    static class DataSource implements Bean {
        DataSource(boolean onClasspath) {
            if (!onClasspath) throw new IllegalStateException("driver class not found");
        }
    }

    static boolean conditionOnClass(Set<String> cp, String cls) { return cp.contains(cls); }
    static boolean conditionOnMissingBean(Set<String> registered, Class<?> type) {
        return !registered.contains(type.getSimpleName());
    }

    public static void main(String[] args) {
        List<String> events = new ArrayList<>();
        List<String> steps = new ArrayList<>();

        steps.add("new SpringApplication(App.class)   -> deduce type SERVLET");
        events.add("ApplicationStartingEvent");
        steps.add("prepareEnvironment()                -> load application.yml + args");
        steps.add("printBanner()");
        steps.add("createApplicationContext()          -> AnnotationConfigServletWebServerApplicationContext");
        steps.add("prepareContext()                    -> run ApplicationContextInitializer");
        steps.add("refreshContext()                    -> parse @Import/@Conditional, register BeanDefinitions");
        events.add("ContextRefreshedEvent");
        events.add("ApplicationStartedEvent");
        events.add("ApplicationReadyEvent");

        System.out.println("=== SpringApplication.run() pipeline (simulated) ===");
        for (int i = 0; i < steps.size(); i++) System.out.println("  " + (i + 1) + ". " + steps.get(i));
        System.out.println();
        System.out.println("=== events published, in order ===");
        for (int i = 0; i < events.size(); i++) System.out.println("  " + (i + 1) + ". " + events.get(i));

        System.out.println();
        System.out.println("=== @Conditional evaluation for DataSourceAutoConfiguration ===");
        Set<String> cp = new LinkedHashSet<>(List.of("java.sql.Driver", "com.zaxxer.hikari.HikariDataSource"));
        Set<String> registered = new LinkedHashSet<>();
        boolean onClass = conditionOnClass(cp, "java.sql.Driver");
        boolean onMissing = conditionOnMissingBean(registered, DataSource.class);
        System.out.println("  @ConditionalOnClass(java.sql.Driver)      : " + onClass);
        System.out.println("  @ConditionalOnMissingBean(DataSource)     : " + onMissing);
        System.out.println("  -> auto-configuration applied             : " + (onClass && onMissing));

        System.out.println();
        System.out.println("=== user registers own DataSource first ===");
        registered.add("DataSource");
        boolean onMissing2 = conditionOnMissingBean(registered, DataSource.class);
        System.out.println("  @ConditionalOnMissingBean(DataSource)     : " + onMissing2);
        System.out.println("  -> auto-configuration applied             : " + (onClass && onMissing2));
        System.out.println("  => user-defined bean always wins (autoconfig is a default, not a mandate)");

        System.out.println();
        System.out.println("=== fail-fast when driver is absent ===");
        try {
            new DataSource(false);
            System.out.println("  constructed (unexpected)");
        } catch (IllegalStateException e) {
            System.out.println("  startup aborted at refreshContext: " + e.getMessage());
            System.out.println("  (context never reaches ApplicationReadyEvent)");
        }
    }
}
